3002\n- **\u4f4d\u7f6e\u7f16\u7801\uff08\u6838\u5fc3\u5dee\u5f02\uff09**\uff1asin(pos\u00b72\u03c0k/P) \u578b\u7f16\u7801\uff0c\u5468\u671f\u53d6\u771f\u5b9e P\uff08\u4e3b\u8bbe\u5b9a\"\u5468\u671f\u5df2\u77e5\"\uff09\uff1bplain Transformer \u5bf9\u7167\u4f7f\u7528\u6807\u51c6\u53ef\u5b66\u4e60/\u5e38\u89c4\u6b63\u5f26\u7f16\u7801\uff0c**\u5176\u4f59\u8d85\u53c2\u4e0e\u521d\u59cb\u5316\u5b8c\u5168\u4e00\u81f4**\uff0c\u4ec5\u4f4d\u7f6e\u7f16\u7801\u4e0d\u540c\u2014\u2014\u9694\u79bb\"\u5468\u671f\u5148\u9a8c\"\u5355\u4e00\u53d8\u91cf\u3002\n- **\u8f93\u5165/\u8f93\u51fa**\uff1a\u56fa\u5b9a\u7a97\u53e3 W=2P\uff0c\u8f93\u51fa H=P \u6b65\u3002\u63a8\u7406\u4e3a\u81ea\u56de\u5f52\uff1a\u7f16\u7801\u4e0a\u4e0b\u6587\u540e\u9010\u6b65\u89e3\u7801\uff0c\u6bcf\u6b65\u5c06\u751f\u6210\u503c\u62fc\u56de\u8f93\u5165\u5e8f\u5217\uff08teacher-forcing \u8bad\u7ec3 + \u81ea\u56de\u5f52\u63a8\u7406\uff09\u3002\n- **W=2P \u7684\u7406\u7531**\uff1a\u81f3\u5c11\u8986\u76d6\u4e24\u4e2a\u5b8c\u6574\u5468\u671f\uff0c\u4f7f\u6a21\u578b\u53ef\u5b66\u4e60\u76f8\u4f4d\u4e0e\u5468\u671f\u5185\u5f62\u72b6\u7684\u4e24\u4e2a\u5b9e\u4f8b\uff0c\u964d\u4f4e\u5355\u5468\u671f\u6837\u672c\u7684\u65b9\u5dee\uff1bH=P \u5bf9\u5e94\"\u9884\u6d4b\u4e00\u4e2a\u5b8c\u6574\u5468\u671f\"\u7684\u5178\u578b\u5355\u89c6\u91ce\u5916\u63a8\u4efb\u52a1\u3002\n- **\u57fa\u7ebf**\uff1a\u2460 seasonal naive\uff08\u0177_{t+h}=y_{t+h\u2212P}\uff0c\u89e3\u6790\u53c2\u7167\uff09\uff1b\u2461 plain Transformer\uff08\u540c\u67b6\u6784\u540c\u9884\u7b97\uff0c\u65e0\u5468\u671f\u7f16\u7801\uff09\uff1b\u2462 \u5c0f\u578b MLP\uff08\u7a97\u53e3\u2192H \u6b65\u76f4\u63a5\u6620\u5c04\uff0c\u975e\u81ea\u56de\u5f52\uff0c\u68c0\u9a8c Transformer \u7ed3\u6784\u672c\u8eab\u7684\u8d21\u732e\uff09\u3002\n\n## 3. \u6570\u636e\uff08\u5408\u6210\uff0c\u4e3b\u6570\u636e\u6e90\uff09\n- **\u751f\u6210**\uff1ay_t = A\u00b7sin(2\u03c0t/P + \u03c6) + \u03b2\u00b7t + \u03b5_t\uff0cA=1\uff0c\u03c6~U(0,2\u03c0)\uff0c\u03b2 \u4f7f\u5168\u7a0b\u8d8b\u52bf\u5e45\u5ea6\u7ea6 0.5\uff0c\u03b5_t~N(0,\u03c3\u00b2)\u3002\n- **\u7f51\u683c**\uff1aP \u2208 {12, 24, 48}\uff1b\u03c3 \u2208 {0.0, 0.1, 0.3}\uff08S/N \u68af\u5ea6\uff09\uff1b\u6bcf\u4e2a (P,\u03c3) \u7ec4\u5408 10 \u6761\u72ec\u7acb\u5e8f\u5217\uff0c\u957f\u5ea6 4096 \u2192 \u5171 90 \u6761\u5e8f\u5217\u3002\n- **\u5207\u5206\u4e0e\u9884\u5904\u7406**\uff1a\u6309\u65f6\u95f4\u987a\u5e8f 70/15/15 \u5207 train/val/test\uff0c**\u7981\u968f\u673a\u6253\u4e71**\uff08\u9632\u6cc4\u6f0f\uff09\uff1bz-score \u6807\u51c6\u5316\u4ec5\u7528 train \u6bb5\u7edf\u8ba1\u91cf\uff1b\u6ed1\u7a97\u6b65\u957f 1 \u6784\u9020 (W\u2192H) \u6837\u672c\u3002\n- **\u516c\u5f00\u5468\u671f\u6570\u636e\u96c6\uff08M4/ETTh \u7b49\uff09**\uff1a\u56e0\u7f51\u7edc\u7981\u7528\u4e14 workspace \u65e0\u6570\u636e\u6587\u4ef6\uff0c**\u4e0d\u8fdb\u5165\u4e3b\u5b9e\u9a8c**\uff1b\u4ec5\u5b9a\u4e49\u4e3a\"\u82e5\u7814\u7a76\u5458\u79bb\u7ebf\u63d0\u4f9b\u6570\u636e\u6587\u4ef6\"\u65f6\u7684\u6269\u5c55\u9879\uff08\u534f\u8bae\u4e0d\u53d8\uff0c\u66ff\u6362\u6570\u636e\u6e90\u5373\u53ef\uff09\u3002\n- **\u5408\u6210\u6570\u636e\u53d6\u820d\u7406\u7531**\uff1a\u73af\u5883\u5f3a\u5236\uff08\u4e0d\u53ef\u4e0b\u8f7d\uff09+ \u79d1\u5b66\u4f18\u52bf\uff08\u5468\u671f\u3001\u566a\u58f0\u3001\u8d8b\u52bf\u3001\u7f3a\u5931\u5747\u53ef\u7cbe\u786e\u63a7\u5236\u4e0e\u6d88\u878d\uff09\u3002\n\n## 4. \u8bad\u7ec3\u6d41\u7a0b\uff08PyTorch\uff0cCPU\uff09\n1. \u56fa\u5b9a\u79cd\u5b50 s \u2208 {1, 7, 42, 123, 2024}\uff08\u63a7\u5236\u6570\u636e\u751f\u6210\u4e2d\u7684 \u03c6/\u03b5 \u4e0e\u6a21\u578b\u521d\u59cb\u5316\u3001dropout\uff09\u3002\n2. Adam\uff0clr=1e-3\uff08\u8d77\u6b65\u503c\uff0c\u5b9e\u73b0\u4e2d\u5141\u8bb8 \u00b11 \u500d\u5fae\u8c03\u4f46\u4e3b\u7ed3\u679c\u7528\u9ed8\u8ba4\uff09\uff0cweight decay 0\uff0c\u68af\u5ea6\u88c1\u526a 1.0\uff0cbatch=32\u3002\n3. \u6700\u591a 50 epoch\uff0c\u65e9\u505c patience=5\uff08val loss\uff09\uff0c\u4fdd\u7559\u6700\u4f18 checkpoint\u3002\n4. \u63a8\u7406\uff1a\u81ea\u56de\u5f52\u9010\u6b65\u751f\u6210 H \u6b65\uff1b\u53cd\u6807\u51c6\u5316\u540e\u8ba1\u7b97\u6307\u6807\u3002\n5. \u4ea4\u4ed8\u4ee3\u7801\u7ed3\u6784\uff1a`data_gen.py`\uff08\u5408\u6210+\u5207\u5206+\u6807\u51c6\u5316\uff09\u3001`models.py`\uff08CycleNet/plain Transformer/MLP\uff0c\u4f4d\u7f6e\u7f16\u7801\u53ef\u5207\u6362\uff09\u3001`baselines.py`\uff08seasonal naive\uff09\u3001`train.py`\u3001`evaluate.py`\u3001`run_all.py`\uff08\u79cd\u5b50\u00d7\u914d\u7f6e\u7f51\u683c\uff09\u3001`requirements.txt` + \u8fd0\u884c\u8bf4\u660e\uff08`pip install torch numpy`\uff0cCPU \u5373\u53ef\uff09\u3002\n\n## 5. \u5bf9\u7167\u3001\u6d88\u878d\u4e0e\u654f\u611f\u6027\n- **\u4e3b\u5bf9\u7167**\uff08\u5168\u7f51\u683c 3P\u00d73\u03c3\u00d75seeds\uff09\uff1aCycleNet vs seasonal naive vs plain Transformer vs MLP\u3002\n- **\u914d\u5bf9\u6bd4\u8f83\uff08\u4e3b\u7ed3\u8bba\u53e3\u5f84\uff0c\u6700\u5e72\u51c0\uff09**\uff1a\u540c\u79cd\u5b50\u3001\u540c\u6570\u636e\u5207\u5206\u3001\u540c\u8d85\u53c2\uff0c\u4ec5\u4f4d\u7f6e\u7f16\u7801\u4e0d\u540c\uff1aCycleNet vs plain Transformer\uff1b\u9010 (seed, \u5e8f\u5217) \u8ba1\u7b97 \u0394nRMSE\uff0c\u62a5\u544a\u5747\u503c\u4e0e\"CycleNet \u66f4\u4f18\"\u7684\u914d\u5bf9\u80dc\u51fa\u7387\u3002\u4e3b\u7ed3\u8bba\u4ee5 **5 \u79cd\u5b50\u65b9\u5411\u4e00\u81f4\u6027**\u4e3a\u51c6\uff08\u4e0d\u4f9d\u8d56\u6b63\u5f0f\u663e\u8457\u6027\u68c0\u9a8c\uff0c\u5df2\u786e\u8ba4\uff09\u3002\n- **\u654f\u611f\u6027\u5206\u6790**\uff08\u540c\u610f\u4e0d\u6269\u5927\u7f51\u683c\uff09\uff1a\n  - (a) \u77ed\u7a97\u53e3\u53d8\u4f53\uff1aW=P\uff08\u4ec5 P=24\u3001\u03c3=0.1 \u4e00\u683c\uff09\uff0c\u68c0\u9a8c\"2 \u4e2a\u5468\u671f\u662f\u5426\u5fc5\u8981\"\uff1b\n  - (b) \u5468\u671f\u9519\u914d\uff1a\u4f4d\u7f6e\u7f16\u7801\u5468\u671f\u53d6 P\u0302=2P \u4e0e P\u0302=P/2\uff08\u4ec5 P=24\u3001\u03c3=0.1 \u4e00\u683c\uff09\uff0c\u68c0\u9a8c H3 \u7684\u4f18\u96c5\u9000\u5316\uff1b\n  - (c) \u566a\u58f0\u68af\u5ea6\uff08\u03c3 \u4e3b\u7f51\u683c\uff09\u4e0e\u5468\u671f\u68af\u5ea6\uff08P \u4e3b\u7f51\u683c\uff09\u672c\u8eab\u5373\u654f\u611f\u6027\u7ef4\u5ea6\u3002\n\n## 6. \u6307\u6807\u4e0e\u5206\u6790\u8ba1\u5212\n- **\u6307\u6807**\uff1atest \u6bb5 MSE\u3001MAE\u3001nRMSE\uff08nRMSE \u7528 train \u6bb5\u6807\u51c6\u5dee\u5f52\u4e00\uff0c\u8de8\u914d\u7f6e\u53ef\u6bd4\uff09\uff1b\u53e6\u62a5\u53c2\u6570\u91cf\u4e0e\u5355 run \u5899\u949f\u65f6\u95f4\u3002\n- **\u805a\u5408**\uff1a\u6bcf\u4e2a\u914d\u7f6e\u5728 10 \u6761\u5e8f\u5217\u4e0a\u805a\u5408\u540e\uff0c\u518d\u8de8 5 \u79cd\u5b50\u62a5 mean\u00b1std\u3002\n- **\u4e3b\u5206\u6790**\uff1a(i) \u5404\u6a21\u578b nRMSE \u5bf9\u6bd4\u8868\uff083P\u00d73\u03c3\uff09\uff1b(ii) \u914d\u5bf9\u6bd4\u8f83 \u0394nRMSE \u4e0e\u80dc\u51fa\u7387\uff08CycleNet vs plain Transformer\uff09\uff1b(iii) CycleNet vs seasonal naive \u5728 \u03c3=0 \u4e0e \u03c3>0 \u7684\u5206\u79bb\u884c\u4e3a\uff08\u9a8c\u8bc1 H2\uff09\u3002\n- **\u654f\u611f\u6027\u5206\u6790**\uff1aW=P \u4e0e W=2P \u5bf9\u6bd4\uff1bP\u0302 \u9519\u914d\u5bf9 nRMSE \u7684\u5f71\u54cd\u5e45\u5ea6\uff1b\u566a\u58f0\u589e\u5927\u65f6 CycleNet \u76f8\u5bf9 plain Transformer \u7684\u4f18\u52bf\u53d8\u5316\u3002\n- **\u62a5\u544a\u51c6\u5219**\uff1a\u4e3b\u7ed3\u8bba = 5 \u79cd\u5b50\u65b9\u5411\u4e00\u81f4 + \u914d\u5bf9\u80dc\u51fa\u7387\uff1b\u4e0d\u505a\u6b63\u5f0f\u663e\u8457\u6027\u68c0\u9a8c\uff08\u5df2\u786e\u8ba4\uff09\uff0c\u4ee5\u6548\u5e94\u91cf\uff08\u0394nRMSE\uff09\u4e0e\u65b9\u5411\u4e00\u81f4\u6027\u5448\u73b0\u3002\n\n## 7. \u53ef\u884c\u6027\u8bba\u8bc1\uff08\u57fa\u4e8e\u5df2\u6838\u5b9e\u73af\u5883\uff09\n**\u5df2\u6838\u5b9e\u4e8b\u5b9e**\uff1a/workspace \u4ec5 task.json\uff08\u65e0\u4ee3\u7801\u65e0\u6570\u636e\uff09\uff1bPython 3.14.4\uff0cnumpy/torch/pandas/scipy/sklearn/matplotlib \u5168\u90e8\u7f3a\u5931\uff1b\u7f51\u7edc\u7981\u7528\u4e14 pip \u5b89\u88c5\u8def\u5f84\u5931\u6548\uff08CA bundle \u9519\u8bef\uff09\uff1b\u65e0 GPU\uff0cCPU 224 \u6838\u3002\n- **PyTorch \u8def\u5f84\uff08\u6b63\u5f0f